import copy,unittest,tempfile
from pathlib import Path
import analyze as a

def setcell(r,name,row,col,value):
 next(c for c in r['tables'][name] if c['row']==row and c['column']==col)['value']=str(value)

def fixture():
 meta={k:'1' for k in a.PROTECTED_META};meta.update(rc='0',ll='-100',deviance='20',rss='.',total_seconds='1',N='1200',ic='4')
 tables={}
 for name,s in a.SCHEMA.items():
  rows=s.get('rownames',['x1'] if name=='status' else [name+'1'])
  tables[name]=[dict(row=r,column=c,value='0') for r in rows for c in s['colnames']]
 tables['coefficients']=[dict(row='x1',column='value',value='2')]
 tables['covariance']=[dict(row='x1',column='x1',value='.5')]
 r=dict(label='smoke',rows_sha256='unchanged',metadata=meta,tables=tables,trace=['FEREG_SOLVER_TRACE|phase=prepared_irls_start|original_rows=100|active_rows=100|finite_columns=1|memory=Fast','FEREG_SOLVER_TRACE|phase=prepared_irls_start|original_rows=1200|active_rows=1200|finite_columns=1|memory=Fast',*[f'FEREG_SOLVER_TRACE|phase=irls_convergence|iteration={i}|passed=1|step=1' for i in range(1,5)],'FEREG_SOLVER_TRACE|phase=strict_decision|iteration=4|certified=1|basis_unchanged=1|rank=1|consistent=1','FEREG_SOLVER_TRACE|phase=strict_result|iteration=4|committed=1|score=1e-10|score_passed=1|converged=1'],observation=dict(status='ok',process_rc=0))
 setcell(r,'certificate','composite_passed','value',1)
 return r

def panel():
 return [dict(fixture(),label=l,workers=w,pair=p,arm=arm) for l in ['akm-1m','dense-1m','dense-4m','sparse-1m'] for w in [1,4,16] for p in [0,1] for arm in ['baseline','candidate']]

def candidate(reuse=True):
 r=fixture();r['arm']='candidate'
 if reuse:
  e=['FEREG_SOLVER_TRACE|phase=h9_producer_accepted|build_weights=1|current_weights=1|sample=1|topology=1|basis=1|cache_bytes=64|identity_bytes=8|envelope=256',
     'FEREG_SOLVER_TRACE|phase=h9_attempt|checkpoint=true|enabled=true|weights=5|basis=1|envelope=256',
     'FEREG_SOLVER_TRACE|phase=h9_geometry|reuse=true|retry=false|workspace=112|historical=80|allowance=256',
     'FEREG_SOLVER_TRACE|phase=h9_result|kind=reused|checkpoint=true|producer=1|consumer=5|rho=22|cache_bytes=64|ledger_bytes=16|workspace=192|envelope=256|iterations=4|operators=5|preconditioners=4|certified=true']
 else:
  e=['FEREG_SOLVER_TRACE|phase=h9_attempt|checkpoint=true|enabled=true|weights=5|basis=1|envelope=256',
     'FEREG_SOLVER_TRACE|phase=h9_result|kind=cold|checkpoint=true|producer=0|consumer=5|rho=NaN|cache_bytes=0|ledger_bytes=0|workspace=192|envelope=256|iterations=0|operators=0|preconditioners=0|certified=true']
 r['trace'][2:2]=e
 return r

class AnalysisTests(unittest.TestCase):
 def test_process_log_preserves_stderr_only_events(self):
  text='startup\nFEREG_SOLVER_TRACE|phase=prepared_irls_start|original_rows=1200\nother output\nFEREG_SOLVER_TRACE|phase=h9_result|kind=cold\n'
  with tempfile.TemporaryDirectory() as directory:
   p=Path(directory)/'process.log';p.write_text(text)
   self.assertEqual(a.read_process_trace(p),[text.splitlines()[1],text.splitlines()[3]])
 def setUp(self): self.a=fixture();self.b=copy.deepcopy(self.a)
 def reject(self,exact=False,cross=False):
  with self.assertRaises(AssertionError): a.compare(self.a,self.b,exact=exact,cross_workers=cross)
 def test_identical(self): self.assertTrue(a.compare(self.a,self.b,exact=True)['passed'])
 def test_coefficient_ulp(self): setcell(self.b,'coefficients','x1','value','2.00000000000001');a.compare(self.a,self.b)
 def test_exact_rejects_ulp(self): setcell(self.b,'coefficients','x1','value','2.00000000000001');self.reject(exact=True)
 def test_coefficient_bound(self): setcell(self.b,'coefficients','x1','value','2.001');self.reject()
 def test_covariance_bound(self): setcell(self.b,'covariance','x1','x1','.501');self.reject()
 def test_sample(self): self.b['rows_sha256']='other';self.reject()
 def test_protected_metadata(self):
  for k in a.PROTECTED_META:
   with self.subTest(k=k):
    self.b=copy.deepcopy(self.a);self.b['metadata'][k]='changed';self.reject()
 def test_certificate(self): setcell(self.b,'certificate','composite_passed','value','0');self.reject()
 def test_trace_decision(self): self.b['trace'][-1]=self.b['trace'][-1].replace('committed=1','committed=0');self.reject()
 def test_solver_discrete_columns(self):
  for col in a.SOLVER_EXACT:
   with self.subTest(col=col):
    self.b=copy.deepcopy(self.a);setcell(self.b,'solver','map',col,1);self.reject()
 def test_runtime_discrete_rows(self):
  for row in a.RUNTIME_EXACT:
   with self.subTest(row=row):
    self.b=copy.deepcopy(self.a);setcell(self.b,'runtime',row,'value',1);self.reject()
 def test_missingness(self): setcell(self.b,'coefficients','x1','value','.');self.reject()
 def test_nonfinite(self): setcell(self.b,'coefficients','x1','value','nan');self.reject()
 def test_unknown_row(self):
  for name in ['fit','runtime','solver']:
   with self.subTest(name=name):
    self.b=copy.deepcopy(self.a);self.b['tables'][name].append(dict(row='unexpected',column='value',value='1'));self.reject()
 def test_shared_missing_table(self):
  for name in a.REQUIRED_TABLES:
   with self.subTest(name=name):
    self.a=fixture();self.b=fixture();del self.a['tables'][name];del self.b['tables'][name];self.reject()
 def test_duplicate_coordinate(self): self.b['tables']['fit'].append(self.b['tables']['fit'][0]);self.reject()
 def test_shared_missing_coordinate(self):
  self.a['tables']['fit'].pop();self.b['tables']['fit'].pop();self.reject()
 def test_cross_workers(self): self.b['metadata']['processors']='4';setcell(self.b,'runtime','threads_effective','value',4);a.compare(self.a,self.b,cross_workers=True)
 def test_cross_worker_objective(self): self.b['metadata']['ll']='-99';self.reject(cross=True)
 def test_cross_worker_strict(self): setcell(self.b,'runtime','strict_profile_rejections','value',1);self.reject(cross=True)
 def test_cross_worker_statistic(self): setcell(self.b,'fit','chi2','value',11);self.reject(cross=True)
 def test_shared_trace_truncation(self):
  self.a['trace']=self.a['trace'][:1];self.b['trace']=self.b['trace'][:1];self.reject()
 def test_shared_trace_field_deletion(self):
  self.a['trace'][-1]=self.a['trace'][-1].replace('|committed=1','');self.b['trace'][-1]=self.a['trace'][-1];self.reject()
 def test_missing_outer_trace(self):
  self.a['trace'].pop(3);self.b['trace'].pop(3);self.reject()
 def test_panel(self): a.validate_records(panel())
 def test_panel_missing(self):
  x=panel();x.pop()
  with self.assertRaises(AssertionError): a.validate_records(x)
 def test_panel_duplicate(self):
  x=panel();x[-1]=x[0]
  with self.assertRaises(AssertionError): a.validate_records(x)
 def test_panel_extra(self):
  x=panel();x.append(x[0])
  with self.assertRaises(AssertionError): a.validate_records(x)
 def test_panel_nonfinite_time(self):
  for value in ['nan','inf','0','-1']:
   with self.subTest(value=value):
    x=panel();x[0]['metadata']['total_seconds']=value
    with self.assertRaises(AssertionError): a.validate_records(x)
 def test_panel_failed(self):
  x=panel();x[0]['observation']['process_rc']=1
  with self.assertRaises(AssertionError): a.validate_records(x)
class ProvenanceTests(unittest.TestCase):
 def test_basis_mismatch(self):
  r=candidate();r['trace']=[s.replace('basis=1','basis=2') if 'phase=h9_attempt' in s else s for s in r['trace']]
  with self.assertRaises(AssertionError): a.provenance(r)
 def test_unfinished_attempt(self):
  r=candidate();r['trace']=[s for s in r['trace'] if 'phase=h9_result' not in s]
  with self.assertRaises(AssertionError): a.provenance(r)
 def test_overlapping_attempt(self):
  r=candidate();r['trace'].insert(4,r['trace'][3])
  with self.assertRaises(AssertionError): a.provenance(r)
 def test_reused_producer_consumed(self):
  r=candidate();r['trace'][6:6]=r['trace'][3:6]
  with self.assertRaises(AssertionError): a.provenance(r)
 def test_cold_attempt_retires_producer(self):
  r=candidate();r['trace'][3]=r['trace'][3].replace('checkpoint=true','checkpoint=false');r['trace'][5]=r['trace'][5].replace('checkpoint=true','checkpoint=false')
  with self.assertRaises(AssertionError): a.provenance(r)
 def test_cold_retry_retires_producer(self):
  r=candidate();r['trace'].insert(4,'FEREG_SOLVER_TRACE|phase=h9_cold_retry')
  with self.assertRaises(AssertionError): a.provenance(r)
 def test_cold_terminal_retires_producer(self):
  r=candidate();cold=candidate(False)['trace'][2:4];r['trace'][3:3]=cold
  with self.assertRaises(AssertionError): a.provenance(r)
 def test_hit(self): self.assertEqual(len(a.provenance(candidate())['hits']),1)
 def test_cold(self): self.assertFalse(a.provenance(candidate(False))['hits'])
 def test_missing_producer(self):
  r=candidate();r['trace']=[s for s in r['trace'] if 'producer_accepted' not in s]
  with self.assertRaises(AssertionError): a.provenance(r)
 def test_retired_producer(self):
  r=candidate();r['trace'].insert(3,'FEREG_SOLVER_TRACE|phase=h9_retired')
  with self.assertRaises(AssertionError): a.provenance(r)
 def test_mutated_terminal(self):
  for before,after in [('producer=1','producer=2'),('checkpoint=true','checkpoint=false'),('rho=22','rho=nan'),('workspace=192','workspace=257'),('certified=true','certified=false'),('iterations=4','iterations=0'),('cache_bytes=64','cache_bytes=65')]:
   with self.subTest(field=before):
    r=candidate();r['trace']=[s.replace(before,after) if 'phase=h9_result' in s else s for s in r['trace']]
    with self.assertRaises(AssertionError): a.provenance(r)
 def test_exact_unaffected(self):
