"""Lossless compact record encoding; templates remove repeated field names."""
import copy,json

def pack(records):
 table_templates=[]; layouts={}; trace_schemas=[]; shapes={}; placements=[]; placement_ids={}; text_lines=[]; line_ids={}; packed=[]; values=[]; value_ids={}
 def intern(value):
  if value not in value_ids:value_ids[value]=len(values);values.append(value)
  return value_ids[value]
 for original in records:
  r=copy.deepcopy(original);r['tables']={}
  for name,rows in original['tables'].items():
   layout=[{k:v for k,v in row.items() if k!='value'} for row in rows]
   signature=json.dumps([name,layout],sort_keys=True)
   if signature not in layouts:
    layouts[signature]=len(table_templates)
    fields=list(rows[0]) if rows else [];assert all(set(row)==set(fields) for row in rows)
    table_templates.append(dict(name=name,fields=fields,rows=[[intern(row[k]) if k=='value' else row[k] for k in fields] for row in rows]))
   index=layouts[signature];template=table_templates[index];base=[dict(zip(template['fields'],row)) for row in template['rows']]
   r['tables'][name]=[index,[[i,intern(row['value'])] for i,row in enumerate(rows) if intern(row['value'])!=base[i]['value']]]
  r['trace']=[]
  for line in original['trace']:
   assert line.startswith('FEREG_SOLVER_TRACE|')
   pairs=[part.split('=',1) for part in line.split('|')[1:]]
   assert all(len(p)==2 for p in pairs)
   keys=tuple(p[0] for p in pairs)
   if keys not in shapes:shapes[keys]=len(trace_schemas);trace_schemas.append(list(keys))
   r['trace'].append([shapes[keys],*[intern(p[1]) for p in pairs]])
  if 'placement' in r['observation']:
   place=r['observation'].pop('placement')
   if 'lscpu' in place:
    lines=place.pop('lscpu').splitlines(keepends=True);ids=[]
    for line in lines:
     if line not in line_ids:line_ids[line]=len(text_lines);text_lines.append(line)
     ids.append(line_ids[line])
    place['lscpu_line_refs']=ids
   key=json.dumps(place,sort_keys=True)
   if key not in placement_ids:placement_ids[key]=len(placements);placements.append(place)
   r['observation']['placement_ref']=placement_ids[key]
  packed.append(r)
 result=dict(table_templates=table_templates,trace_schemas=trace_schemas,placements=placements,text_lines=text_lines,values=values,records=packed)
 assert unpack(result)==records
 return result

def unpack(encoded):
 records=[]
 for packed in encoded['records']:
  r=copy.deepcopy(packed);r['tables']={}
  for name,(index,changes) in packed['tables'].items():
   template=encoded['table_templates'][index];rows=[dict(zip(template['fields'],row)) for row in template['rows']]
   assert encoded['table_templates'][index]['name']==name
   for i,value in changes:rows[i]['value']=value
   for row in rows:row['value']=encoded['values'][row['value']]
   r['tables'][name]=rows
  r['trace']=['FEREG_SOLVER_TRACE|'+'|'.join(k+'='+encoded['values'][v] for k,v in zip(encoded['trace_schemas'][e[0]],e[1:])) for e in packed['trace']]
  if 'placement_ref' in r['observation']:r['observation']['placement']=copy.deepcopy(encoded['placements'][r['observation'].pop('placement_ref')])
  if 'placement' in r['observation'] and 'lscpu_line_refs' in r['observation']['placement']:
   place=r['observation']['placement'];place['lscpu']=''.join(encoded['text_lines'][i] for i in place.pop('lscpu_line_refs'))
  records.append(r)
 return records

