"""Frozen H9f comparisons; timings cannot override a scientific failure."""
import math, statistics, json
from pathlib import Path
SCHEMA=json.loads(Path(__file__).with_name("schema.json").read_text())
REQUIRED_TABLES=set(SCHEMA)|{"coefficients","covariance"}
PROTECTED_META = {'rc','processors','processors_licensed','ic','iterations','feppml_iterations','feppml_converged','N','rank','df_a','df_m','df_r','df_resid','N_clust','num_singletons','separated','converged','fereg_threads','feppml_threads','slope_omissions','finite_slope_rank','covariance_policy','complete'}
TRACE_FIELDS = {
 'prepared_irls_start': ['original_rows','active_rows','finite_columns','memory'],
 'ordinary_linear_route': ['joint','basis_columns','response_generation','weight_generation','mode'],
 'irls_convergence': ['iteration','passed','step'],
 'strict_decision': ['iteration','certified','basis_unchanged','rank','consistent'],
 'strict_result': ['iteration','committed','score_passed','converged'],
 'profile_recovery': ['iteration','action'],
 'checkpoint_profile_refinement': ['previous','next'],
 'joint_strict_direction': ['refusal','consistent'],
 'joint_strict_final': ['accepted','basis_unchanged'],
 'profile_final_products': ['accepted','reason'],
 'final_hessian_decision': ['decision'],
 'separation_projection': ['generation','rows','solver'],
 'ir_fixed_point_check': ['passed'],
}
RUNTIME_EXACT = {'outer_iterations','step_halvings','memory_requested','memory_selected','linear_route','fallback_mask','fallback_count','threads_requested','threads_effective','strict_profile_rejections','two_consecutive_convergence','rank_frozen','workspace_allocation_free','iteration_allocation_free','allocation_audit_present','ppml_capacity_stable','linear_capacity_stable','audit_scratch_stable','audit_route_qualified','linear_session_allocation_free','fresh_warm_equivalent','allocation_certificate_passed'}
SOLVER_EXACT = {'requested_family','selected_family','selected_engine','effective_family','effective_engine','checkpoint_family','row_engine','ordinary_frames','checkpoint_frames','retries','fallback_count','fallback_reason'}
FIT_CONTINUOUS = {'deviance','ll','r2_p','chi2'}
INFERENCE_CONTINUOUS = {'psd_raw_minimum_eigenvalue','psd_final_minimum_eigenvalue','psd_eigensystem_recon_relinf','psd_orthogonality_relinf','psd_clipped_recon_relinf'}

def number(s):
 s=str(s).strip()
 return None if s.startswith('.') and (s=='.' or len(s)==2 and s[1].isalpha()) else float(s)

def close(a,b,rtol,atol):
 a,b=number(a),number(b)
 if a is None or b is None:
  assert a is None and b is None, 'missingness changed'
  return 0.
 assert math.isfinite(a) and math.isfinite(b),'nonfinite science'
 ratio=abs(a-b)/(atol+rtol*max(abs(a),abs(b)))
 assert ratio<=1, (a,b,ratio)
 return ratio

def table(record,name):
 rows=record['tables'][name]
 result={(x.get('row',x.get('name')),x.get('column','value')):x['value'].strip() for x in rows}
 assert len(rows)==len(result),('duplicate matrix coordinate',name)
 return result

def schema(record):
 assert set(record['tables'])==REQUIRED_TABLES,'missing or unexpected tables'
 for name,expected in SCHEMA.items():
  t=table(record,name)
  assert t,('empty table',name)
  rows={r for r,c in t};cols={c for r,c in t}
  assert cols==set(expected['colnames']),('column schema',name)
  if 'rownames' in expected: assert rows==set(expected['rownames']),('row schema',name)
  assert len(t)==len(rows)*len(cols),('incomplete rectangle',name)
 b=table(record,'coefficients');v=table(record,'covariance')
 names={r for r,c in b}
 assert b and all(c=='value' for r,c in b)
 assert set(v)=={(r,c) for r in names for c in names},'covariance layout'
 assert {r for r,c in table(record,'status')}==names,'status axis'

def validate_records(records):
 expected={(l,w,p,a) for l in ['akm-1m','dense-1m','dense-4m','sparse-1m'] for w in [1,4,16] for p in [0,1] for a in ['baseline','candidate']}
 keys=[(r['label'],r['workers'],r['pair'],r['arm']) for r in records]
 assert len(keys)==len(set(keys))==48 and set(keys)==expected,'panel completeness'
 for r in records:
  assert r['observation']['status']=='ok' and r['observation']['process_rc']==0
  assert r['metadata']['rc']=='0' and r['metadata']['complete']=='1'
  value=float(r['metadata']['total_seconds'])
  assert math.isfinite(value) and value>0,'invalid timing'
  schema(r)

def events(record):
 result=[]
 for line in record['trace']:
  if 'FEREG_SOLVER_TRACE|' not in line: continue
  parts=line.split('FEREG_SOLVER_TRACE|',1)[1].split('|')
  e=dict(p.split('=',1) for p in parts if '=' in p)
  phase=e.get('phase')
  if phase in TRACE_FIELDS:
   required=set(TRACE_FIELDS[phase])
   if phase=='joint_strict_direction':
    assert ('refusal' in e) != ('consistent' in e),'joint trace variant'
    required={'refusal'} if 'refusal' in e else {'consistent'}
   if phase=='profile_final_products' and e.get('accepted')=='1': required={'accepted'}
   assert required<=e.keys(),('incomplete protected trace',phase)
  result.append(e)
 return result

def trace_complete(record):
 es=events(record)
 starts=[i for i,e in enumerate(es) if e.get('phase')=='prepared_irls_start']
 assert len(starts)>=2,'initialization/target trace missing'
 target=es[starts[-1]:];start=target[0]
 expected_rows={'smoke':1200,'akm-1m':1000000,'dense-1m':1000000,'dense-4m':4000000,'sparse-1m':1000000}[record['label']]
 assert int(start['original_rows'])==expected_rows,'target trace row axis'
 assert int(start['active_rows'])==int(float(record['metadata']['N'])),'target active sample'
 count=int(float(record['metadata']['ic']))
 ordinary=[int(e['iteration']) for e in target if e.get('phase')=='irls_convergence']
 assert ordinary==list(range(1,count+1)),'incomplete target outer trace'
 strict=[e for e in target if e.get('phase')=='strict_result']
 decisions=[e for e in target if e.get('phase')=='strict_decision']
 joint=[e for e in target if e.get('phase')=='joint_strict_final' and e.get('accepted')=='1']
 assert strict or joint,'target terminal checkpoint missing'
 if strict:
  assert all(any(d['iteration']==r['iteration'] for d in decisions) for r in strict),'strict decision missing'
  if not joint:
   assert strict[-1]['converged']=='1' and strict[-1]['committed']=='1' and strict[-1]['score_passed']=='1','target strict result not accepted'
   assert int(strict[-1]['iteration'])==count,'target terminal iteration'
 return target

def decisions(record):
 trace_complete(record)
 return [(e['phase'],{k:e[k] for k in TRACE_FIELDS[e['phase']] if k in e}) for e in events(record) if e.get('phase') in TRACE_FIELDS]

def provenance(record):
 target=trace_complete(record)
 accepted=None;attempt=None;results=[];hits=[];attempted_reuse=False
 for e in target:
  phase=e.get('phase')
  if phase=='h9_producer_accepted':
   keys={'build_weights','current_weights','sample','topology','basis','cache_bytes','identity_bytes','envelope'}
   assert keys<=e.keys(),'incomplete accepted producer'
   assert int(e['cache_bytes'])+int(e['identity_bytes'])<=int(e['envelope'])
   assert int(e['build_weights'])<=int(e['current_weights'])
   accepted=e
  elif phase in {'h9_retired','h9_cold_retry'}: accepted=None
  elif phase=='h9_attempt':
   assert {'checkpoint','enabled','weights','basis','envelope'}<=e.keys()
   assert attempt is None,'overlapping H9 attempts'
   if e['checkpoint']=='false': accepted=None
   attempt=e
  elif phase=='h9_geometry' and e.get('reuse')=='true': attempted_reuse=True
  elif phase=='h9_result':
   required={'kind','checkpoint','producer','consumer','rho','cache_bytes','ledger_bytes','envelope','iterations','operators','preconditioners','certified'}
   required|={'reason'} if e.get('kind')=='declined' else {'workspace'}
   assert required<=e.keys(),'incomplete H9 terminal event'
   assert e['kind'] in {'reused','cold_retry','cold','declined'}
   assert e['certified']==('false' if e['kind']=='declined' else 'true')
   assert attempt is not None and attempt['checkpoint']==e['checkpoint'] and attempt['weights']==e['consumer']
   results.append(e)
   if e['kind']=='reused':
    assert accepted is not None,'reuse lacks accepted producer'
    assert accepted['basis']==attempt['basis'],'reuse basis changed'
    assert e['checkpoint']=='true' and attempt['enabled']=='true','reuse outside checkpoint'
    assert e['producer']==accepted['build_weights'] and e['cache_bytes']==accepted['cache_bytes']
    assert int(e['consumer'])>=int(e['producer'])
    rho=float(e['rho']);assert math.isfinite(rho) and rho>=1,'invalid normalized drift'
    assert int(e['cache_bytes'])+int(e['ledger_bytes'])<=int(e['workspace'])<=int(e['envelope'])
    assert int(e['iterations'])>0 and int(e['operators'])>=int(e['iterations']) and int(e['preconditioners'])>0
    hits.append(e)
   attempt=None;accepted=None
 assert attempt is None,'unterminated H9 attempt'
 if record['arm']=='candidate': assert results,'candidate H9 terminal diagnostics absent'
 else: assert not results and not hits,'baseline modified by H9'
 return dict(passed=True,attempted_reuse=attempted_reuse,hits=hits,results=results)

def compare_pair(a,b):
 pa,pb=provenance(a),provenance(b)
 result=compare(a,b,exact=not pb['attempted_reuse'])
 result['baseline_provenance']=pa
 result['candidate_provenance']=pb
 return result

def compare(a,b,exact=False,cross_workers=False):
 schema(a);schema(b)
 assert a['rows_sha256']==b['rows_sha256'],'sample/row order changed'
 assert a['metadata'].keys()==b['metadata'].keys(),'metadata layout changed'
 for k in PROTECTED_META-({'processors','fereg_threads','feppml_threads'} if cross_workers else set()):
  assert k in a['metadata'] and a['metadata'][k]==b['metadata'][k],('protected metadata',k)
 for k in ['ll','deviance','rss']:
  if exact: assert a['metadata'][k]==b['metadata'][k],k
  else: close(a['metadata'][k],b['metadata'][k],1e-7,1e-9)
 assert decisions(a)==decisions(b),'protected trace decision changed'
 assert a['tables'].keys()==b['tables'].keys(),'matrix layout changed'
 maxima={}
 for name in a['tables']:
  ta,tb=table(a,name),table(b,name)
  assert ta.keys()==tb.keys(),('matrix coordinates changed',name)
  maximum=0.
  for (row,col),va in ta.items():
   vb=tb[(row,col)]
   if name=='runtime':
    if row in RUNTIME_EXACT-({'threads_requested','threads_effective'} if cross_workers else set()): assert va==vb,(name,row)
    continue
   if name=='solver' and col.endswith('_seconds'): continue
   if exact:
    assert va==vb,(name,row,col,va,vb)
    continue
   if name=='coefficients': maximum=max(maximum,close(va,vb,1e-7,1e-10))
   elif name=='covariance': maximum=max(maximum,close(va,vb,1e-6,1e-10))
   elif name=='fit' and row=='inner_iterations': pass
   elif name=='fit' and row in FIT_CONTINUOUS: maximum=max(maximum,close(va,vb,1e-7,1e-9))
   elif name=='inference' and row in INFERENCE_CONTINUOUS: maximum=max(maximum,close(va,vb,1e-6,1e-10))
   elif name=='certificate' and row!='composite_passed':
    assert all(number(v) is not None and math.isfinite(number(v)) and number(v)>=0 for v in (va,vb))
   elif name=='solver' and col not in SOLVER_EXACT:
    assert (number(va) is None)==(number(vb) is None),'solver missingness'
    assert all(number(v) is None or math.isfinite(number(v)) for v in (va,vb))
   else: assert va==vb,(name,row,col,va,vb)
  maxima[name]=maximum
 assert number(table(a,'certificate')[('composite_passed','value')])==1
 assert number(table(b,'certificate')[('composite_passed','value')])==1
 return dict(passed=True,exact=exact,max_normalized_errors=maxima)

def summarize(records):
 validate_records(records)
 cells=[]
 for label in ['akm-1m','dense-1m','dense-4m','sparse-1m']:
  for workers in [1,4,16]:
   rows=[r for r in records if r['label']==label and r['workers']==workers]
   pairs=[]
   for rep in [0,1]:
    arms={r['arm']:r for r in rows if r['pair']==rep}
    assert set(arms)=={'baseline','candidate'}
    a,b=arms['baseline'],arms['candidate']
    science=compare_pair(a,b)
    ta,tb=float(a['metadata']['total_seconds']),float(b['metadata']['total_seconds'])
    assert ta>0 and tb>0
    pairs.append(dict(pair=rep,baseline_seconds=ta,candidate_seconds=tb,ratio=tb/ta,delta_seconds=tb-ta,science=science))
   for arm in ['baseline','candidate']:
    same=[r for r in rows if r['arm']==arm]
    compare(same[0],same[1],exact=True)
    assert provenance(same[0])==provenance(same[1]),'fixed-worker H9 work/provenance changed'
   deltas=[p['delta_seconds'] for p in pairs]
   medbase=statistics.median(p['baseline_seconds'] for p in pairs)
   cells.append(dict(label=label,workers=workers,pairs=pairs,median_ratio=statistics.median(p['ratio'] for p in pairs),nonregression=statistics.median(p['delta_seconds']/max(.05*p['baseline_seconds'],.001) for p in pairs)<=1,target_pass=all(p['ratio']<=.95 for p in pairs) if label=='dense-4m' and workers in [4,16] else None))
 # Compare each arm across workers against its own one-worker result. Worker identity is expected to differ.
 for label in ['akm-1m','dense-1m','dense-4m','sparse-1m']:
  for arm in ['baseline','candidate']:
   group=[r for r in records if r['label']==label and r['arm']==arm and r['pair']==0]
   reference=next(r for r in group if r['workers']==1)
   for r in group:
    compare(reference,r,cross_workers=True)
 reuse_gate=all(any(provenance(r)['hits'] for r in records if r['label']==label and r['workers']==workers and r['arm']=='candidate' and r['pair']==pair) for label in ['dense-1m','dense-4m'] for workers in [1,4,16] for pair in [0,1])
 performance_gate=all(c['nonregression'] and c['target_pass'] is not False for c in cells)
 return dict(cells=cells,science_passed=True,completeness_passed=True,repeatability_passed=True,provenance_passed=True,reuse_gate=reuse_gate,performance_gate=performance_gate,passed=reuse_gate and performance_gate)
